import{_ as r,a0 as i,w as a,s as d,I as o,x as s,a1 as e,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"GNOME 新终端程序尝鲜 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME 新终端程序尝鲜 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME 新终端程序尝鲜 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME 新终端程序尝鲜 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220430 Hands On With GNOME’s New Terminal for Linux Users","title":"GNOME 新终端程序尝鲜","tag":"202205","desc":""},"relativePath":"202205/20220430 Hands On With GNOME’s New Terminal for Linux Users.md","filePath":"[post].md"}'),u={name:"202205/20220430 Hands On With GNOME’s New Terminal for Linux Users.md"};function m(f,t,g,N,M,O){const n=i("Link");return a(),d("div",null,[t[33]||(t[33]=o("h1",{id:"gnome-新终端程序尝鲜",tabindex:"-1"},[s("GNOME 新终端程序尝鲜 "),o("a",{class:"header-anchor",href:"#gnome-新终端程序尝鲜","aria-label":"Permalink to “GNOME 新终端程序尝鲜”"},"​")],-1)),o("p",null,[t[1]||(t[1]=s("几天前，我分享了我 ",-1)),e(n,{href:"https://itsfoss.com/gnome-text-editor/"},{default:l(()=>[...t[0]||(t[0]=[s("对新 GNOME 文本编辑器的体验",-1)])]),_:1}),t[2]||(t[2]=s("，它是原编辑器 Gedit 的替代品。",-1))]),o("p",null,[t[5]||(t[5]=s("但它并不是唯一的应用程序替代品。GNOME 42 还有一个新的终端，叫做 ",-1)),o("ruby",null,[e(n,{href:"https://gitlab.gnome.org/GNOME/console"},{default:l(()=>[...t[3]||(t[3]=[s("控制台",-1)])]),_:1}),t[4]||(t[4]=o("rt",null,"Console",-1))]),t[6]||(t[6]=s("。",-1))]),t[34]||(t[34]=p('<p>让我来分享一下 GNOME 提供的这个新终端的新功能，以及它的使用体验吧！</p><h3 id="控制台-gnome-的新终端模拟器" tabindex="-1">控制台：GNOME 的新终端模拟器 <a class="header-anchor" href="#控制台-gnome-的新终端模拟器" aria-label="Permalink to “控制台：GNOME 的新终端模拟器”">​</a></h3><p>这个新应用程序的目标是提供一个“简单的、用户友好的终端模拟器”。它确实“简单”，因为它没有提供以往 GNOME 终端下用户习惯的许多功能。</p><p>后面我会继续谈这个话题。让我们先看看 GNOME 控制台的新功能。</p><h4 id="桌面通知" tabindex="-1">桌面通知 <a class="header-anchor" href="#桌面通知" aria-label="Permalink to “桌面通知”">​</a></h4><p>Ubuntu 上的 GNOME 终端从来没有这个功能，不过我在 elementary 和 Fedora 等发行版中看到过。</p><p>这是一个很方便的功能，当一个长期运行的命令执行完毕时，终端会发送一个桌面通知。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/notification-from-gnome-console.png" alt="GNOME 控制台的通知"></p><p>如果你在命令正在运行的同时，需要做其他事情，那么得到命令完成的通知有助于你保持工作效率。</p><h4 id="进行-root-和-ssh-操作时改变窗口颜色" tabindex="-1">进行 root 和 SSH 操作时改变窗口颜色 <a class="header-anchor" href="#进行-root-和-ssh-操作时改变窗口颜色" aria-label="Permalink to “进行 root 和 SSH 操作时改变窗口颜色”">​</a></h4><p>这很可能是我在其他终端程序中没有见过的独特功能。</p>',11)),o("p",null,[t[8]||(t[8]=s("当你用 ",-1)),t[9]||(t[9]=o("code",null,"sudo",-1)),t[10]||(t[10]=s(" 运行命令或 ",-1)),e(n,{href:"https://itsfoss.com/root-user-ubuntu/"},{default:l(()=>[...t[7]||(t[7]=[s("切换到 root 用户",-1)])]),_:1}),t[11]||(t[11]=s(" 时，应用程序窗口会变成红色。",-1))]),t[35]||(t[35]=p('<p><img src="https://itsfoss.com/wp-content/uploads/2022/04/GNOME-Console-turns-red-when-using-sudo-or-root-800x442.webp" alt="GNOME 控制台在使用 sudo 或 root 用户时变成红色"></p><p>我想它的目的是警告用户他们正在使用高级权限，因此在运行命令时要小心。</p><p>同样，如果你使用 SSH 连接到一个远程服务器，终端应用程序窗口的颜色会变成紫色。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/gnome-console-color-change-ssh.png" alt="GNOME 控制台在 SSH 连接时变成紫色"></p><p>这也是提醒用户命令正在远程 Linux 机器上运行，而不是在本地机器上运行的好方法。</p><h4 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to “主题”">​</a></h4><p>遵循新的设计准则，控制台提供了三种主题：浅色、深色和跟随系统。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/themes-gnome-console.png" alt="GNOME 控制台主题"></p><p>控制台默认使用系统主题，它根据你的操作系统的深浅主题而改变终端配色。你也可以单独使用控制台的浅色/深色主题，而不用改变系统主题。</p>',9)),o("p",null,[t[13]||(t[13]=s("关于主题的内容差不多就这些。你可以进行的 ",-1)),e(n,{href:"https://itsfoss.com/customize-linux-terminal/"},{default:l(()=>[...t[12]||(t[12]=[s("终端定制",-1)])]),_:1}),t[14]||(t[14]=s(" 并不多。",-1))]),t[36]||(t[36]=p('<h3 id="关闭终端窗口时更好的警告" tabindex="-1">关闭终端窗口时更好的警告 <a class="header-anchor" href="#关闭终端窗口时更好的警告" aria-label="Permalink to “关闭终端窗口时更好的警告”">​</a></h3><p>当你试图关闭一个仍在运行的命令时，老的 GNOME 终端也会显示一个警告。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/warning-in-old-gnome-terminal.png" alt="旧版 GNOME 终端中的警告"></p><p>这个警告在新的 GNOME 控制台中稍好一些，因为它也会显示正在运行的命令。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/05/warning-in-new-gnome-console.png" alt="新版 GNOME 控制台中的警告"></p><h4 id="透明界面" tabindex="-1">透明界面 <a class="header-anchor" href="#透明界面" aria-label="Permalink to “透明界面”">​</a></h4><p>GNOME 控制台默认有一个透明界面。在正常模式下，你可以透过它看到一点背景。</p><p>例如，你可以看到背景程序中的一些模糊的文字。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/transparent-gnome-console.png" alt="GNOME 控制台的透明界面"></p><p>我注意到，当控制台进入全屏模式时，界面不再透明。而且，你无法配置透明度。</p><h4 id="其他功能" tabindex="-1">其他功能 <a class="header-anchor" href="#其他功能" aria-label="Permalink to “其他功能”">​</a></h4><p>谢天谢地，你可以在控制台中使用标签。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/tabs-GNOME-Console.png" alt="标签式界面"></p><p>你可以执行与以往 GNOME 终端一样的搜索操作。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/search-GNOME-Console.png" alt="GNOME 控制台中的搜索操作"></p><p>它没有太多的选项。<ruby>汉堡菜单<rt>hamburger menu</rt></ruby>让你一眼就能看到所有可用的键盘快捷键。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/keyboard-shortcuts-gnome-console.png" alt="GNOME 控制台中的键盘快捷键"></p><p>以上就是关于 GNOME 控制台的一切。</p><h3 id="在-ubuntu-22-04-上安装-gnome-控制台" tabindex="-1">在 Ubuntu 22.04 上安装 GNOME 控制台 <a class="header-anchor" href="#在-ubuntu-22-04-上安装-gnome-控制台" aria-label="Permalink to “在 Ubuntu 22.04 上安装 GNOME 控制台”">​</a></h3><p>如果你的发行版使用了原版 GNOME 42，那么它应该默认提供了新终端。</p><p>尽管 Ubuntu 22.04 使用的是 GNOME 42，但它仍然使用旧的 GNOME 终端。不过，你可以使用下面的命令来安装新的控制台。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-console</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你可能会想，既然我们已经有了一个更好的、功能更强的 GNOME 终端，为什么还要开发一个新的控制台呢？这是因为 GNOME 有了新的设计指南。改造这些应用程序的旧代码库太复杂了，可能也不大划算，从头开始写反而会更容易，因此你会看到更多的“新的” GNOME 应用程序，如控制台和文本编辑器。</p><p>由于这个新的应用程序的目标是让事情更简单，因此它没有提供很多功能。你不能定制它，改变颜色、字体等。由于不支持定制，所以也不需要配置文件。</p>',25)),o("p",null,[t[16]||(t[16]=s("对于很少使用终端的人来说，控制台已经够用了。不过，我认为应该增加在输入密码时显示星号的功能。其他 ",-1)),e(n,{href:"https://itsfoss.com/best-linux-beginners/"},{default:l(()=>[...t[15]||(t[15]=[s("面向初学者的发行版",-1)])]),_:1}),t[17]||(t[17]=s("，如 Mint，就使用了这个功能，从而避免对 Linux 新手用户造成困扰。",-1))]),t[37]||(t[37]=o("p",null,"你如何看待这个新的 GNOME 控制台，以及这种创建“新的 GNOME 应用程序”的方式呢？欢迎在下方评论区发表你的看法。",-1)),t[38]||(t[38]=o("hr",null,null,-1)),o("p",null,[t[19]||(t[19]=s("via: ",-1)),e(n,{href:"https://itsfoss.com/gnome-console/"},{default:l(()=>[...t[18]||(t[18]=[s("https://itsfoss.com/gnome-console/",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=s("作者：",-1)),e(n,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[20]||(t[20]=[s("Abhishek Prakash",-1)])]),_:1}),t[25]||(t[25]=s(" 选题：",-1)),e(n,{href:"https://github.com/lkxed"},{default:l(()=>[...t[21]||(t[21]=[s("lkxed",-1)])]),_:1}),t[26]||(t[26]=s(" 译者：",-1)),e(n,{href:"https://github.com/lkxed"},{default:l(()=>[...t[22]||(t[22]=[s("lkxed",-1)])]),_:1}),t[27]||(t[27]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...t[23]||(t[23]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[30]||(t[30]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[28]||(t[28]=[s("LCTT",-1)])]),_:1}),t[31]||(t[31]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...t[29]||(t[29]=[s("Linux中国",-1)])]),_:1}),t[32]||(t[32]=s(" 荣誉推出",-1))])])}const G=r(u,[["render",m]]);export{h as __pageData,G as default};
